# ======================= التوأم (المبدأ 5، الفحوص المستقلة B–E، الدرس 132) =======================
# بعد الحلّ المشترك أو الكشف في التمرين والعلاج واللعب بند توأم: المهارة نفسها مسألةً جديدة يحلّها الطفل وحده.
# المهارة هنا بعدد الأشياء (رتّب ثلاثة غير رتّب خمسة) وبهيئة السؤال (ملتوٍ، أو بدايات غير محاذاة)، فيأتي التوأم بصعوبة أصله
def skill(it):
    t = it['t']
    if t == 'lenPick': return 'len|%s|%s|%d' % (it.get('ask', 'long'), 'w' if it.get('wavy') else 's' if any(it.get('shift') or []) else 'a', len(it['lens']))
    if t == 'orderBy': return 'order|%s|%s|%d' % (it.get('by', 'len'), it.get('dir', 'up'), len(it['vals']))
    if t == 'sizePick': return 'size|%s|%d' % (it.get('ask', 'big'), len(it['vals']))
    if t == 'balance': return 'wt|%s|%s' % (it.get('mode', 'read'), it.get('ask', 'heavy'))
    if t in ('unitCount', 'unitLay'): return ('meas|' if t == 'unitCount' else 'lay|') + it['unit']
    if t == 'unitCheck': return 'ucheck|' + it['bad']
    if t == 'spanPick': return 'span|' + it.get('ask', 'longer')
    if t == 'transPick':   # فخّ البند: جوابه «بطوله» (same)، أو «أطول/أقصر» وصاحبه «بطوله» (vsSame)، أو لا «بطوله» فيه (الفحص المستقل F1 (5))
        lg = (it.get('ask', 'longer') == 'longer') == (it['la'] > it['lb']); ca, co = scat(it['la'] if lg else it['lb']), scat(it['lb'] if lg else it['la'])
        return 'trans|' + ('same' if ca == 'same' else 'vsSame' if co == 'same' else 'none')   # وسلّة الجواب: «بطول الشبر» غير «أطول منه» (الفحص المستقل C2)
    if t == 'barRead': return 'bar|' + it['ask'] + ('|' + it['cat'] if it['ask'] == 'count' else '|' + it['a'] + '>' + it['b'] if it['ask'] == 'more' else '')   # «كم تفاحة؟» جملته بفئته
    if t == 'rodMatch': return 'teen|match|' + it.get('dir', 'card')
    if t == 'makeTen': return 'mt|' + it.get('ask', 'total') + ('|story' if it.get('story') else '')
    if t == 'backTen': return 'bt' + ('|story' if it.get('story') else '')
    return {'spanSort': 'ssort', 'barBuild': 'barb', 'rodCount': 'teen|count', 'rodBuild': 'teen|build', 'teenCmp': 'teencmp', 'teenTrace': 'trace',
            'frameNeed': 'friend', 'framePaint': 'fpaint', 'frameGlance': 'fglance'}.get(t, t)
def s2n(a): return ','.join(str(x) for x in sorted(a))
def fact(it):   # مفتاح المسألة كما في build/d240.mjs (للمقارنة هنا فقط؛ والفحص الحاسم هناك)
    t = it['t']
    if t == 'lenPick': return 'len|%s|%s|%s|%s' % (it.get('ask', 'long'), s2n(it['lens']), 's' if any(it.get('shift') or []) else 'a', 'w' if it.get('wavy') else '')
    if t == 'orderBy': return 'order|%s|%s|%s' % (it.get('by', 'len'), it.get('dir', 'up'), s2n(it['vals']))
    if t == 'sizePick': return 'size|%s|%s' % (it.get('ask', 'big'), s2n(it['vals']))
    if t == 'balance': return 'wt|' + ','.join(sorted([it['a'], it['b']]))
    if t == 'unitCount': return 'meas|%s|%d' % (it['unit'], it['n'])   # بمهمته ووحدته وعدده بلا الشيء (الفحص المستقل A)
    if t == 'unitLay': return 'lay|%s|%d' % (it['unit'], it['n'])
    if t == 'unitCheck': return 'ucheck|%s|%s|%d' % (it['bad'], it['unit'], it['n'])
    if t == 'spanPick': return 'span|' + s2n([it['a'], it['b']])
    if t == 'spanSort': return 'ssort|%s|%d' % (it['obj'], it['len'])
    if t == 'transPick': return 'trans|' + ','.join(sorted([it['a'], it['b']]))   # الزوج نفسه مسألة واحدة أطولَ سُئل أم أقصر
    if t == 'barRead': return 'bar|%s|%s|%s' % (it['ask'], ','.join(map(str, it['counts'])), it.get('cat') or '>'.join(x for x in (it.get('a'), it.get('b')) if x))
    if t == 'barBuild': return 'barb|' + ','.join(map(str, it['counts']))
    if t in ('rodCount', 'rodBuild', 'rodMatch'): return 'teen|%s|%d' % ({'rodCount': 'read', 'rodBuild': 'build', 'rodMatch': 'read'}[t], it['n'])   # القراءة مسألة واحدة (عدّاً أو بطاقةً أو بناءً)
    if t == 'teenCmp': return 'teencmp|' + s2n([it['a'], it['b']])
    if t == 'teenTrace': return 'trace|%d' % it['n']
    if t == 'frameNeed': return 'friend|%d' % it['n']
    if t == 'frameGlance': return 'fglance|%d' % it['n']
    if t == 'makeTen': return 'friend|%d' % it['a'] if it.get('ask') == 'moved' else 'add|' + s2n([it['a'], it['b']])
    if t == 'backTen': return 'sub|%d|%d' % (it['a'], it['b'])
    return None
FMT = {'how', 'q', 'line', 'prompt', 'why', 'err', 'errs', 'names', 'tag', 'x240', 'c', 'twin'}
def tkey(it):   # ما لا مسألة له في d240 (لوّن صديقين) يُقارَن بجوهره، كما يقارن d240 التوأم بأصله (norm)
    return fact(it) or json.dumps({k: v for k, v in it.items() if k not in FMT}, ensure_ascii=False, sort_keys=True)
import re
ASSESS_ONLY = re.compile(r'^(count|friend|fglance)\|')   # كما في d240: تُحسب بين التقييمات وحدها
# ما يعرضه المشهد قبل التمرين (SCENE_FACTS في d240، لمشاهد الوحدة)
CAT = lambda L: 'short' if L < SPAN_S * .85 else 'long' if L > SPAN_S * 1.15 else 'same'
def scene_facts(s):
    k = s.get('scene')
    if k in ('pencilHook', 'alignExplore', 'chaosEnds'): return ['len|long|%s|s|' % s2n(s['lens'])]
    if k == 'wormRace': return ['len|%s|%s|%s|' % (r.get('ask', 'long'), s2n(r['lens']), 's' if any(r.get('shift') or []) else 'a') for r in s['rounds']]
    if k == 'ballStoneHook': return ['wt|beachBall,stone']
    if k == 'balanceLab': return ['wt|' + ','.join(sorted(p)) for p in s['pairs']]
    if k == 'gardenBalance': return ['wt|' + ','.join(sorted(p)) for p in s['rounds']]
    if k == 'chaosHeavyBadge': return ['wt|' + ','.join(sorted([s['big'], s['small']]))]
    if k == 'gapsHook': return ['ucheck|gap|clip|%d' % s['n']]
    if k == 'clipLay': return ['lay|clip|%d' % s['n'][0], 'meas|clip|%d' % s['n'][0], 'lay|cube|%d' % s['n'][1], 'meas|cube|%d' % s['n'][1]]
    if k == 'spansTable': return ['span|' + s2n([s['a'], s['b']])]
    if k == 'chaosStartMid': return ['meas|clip|%d' % s['n'], 'ucheck|start|clip|%d' % s['n']]
    if k == 'contractorBoard':
        c = {'short': 0, 'same': 0, 'long': 0}
        for _, L in s['house']: c[CAT(L)] += 1
        n = ','.join(str(c[x]) for x in ('short', 'same', 'long'))
        return ['ssort|%s|%d' % (o, L) for o, L in s['house']] + (['trans|' + ','.join(sorted(s['trans']['pair']))] if s.get('trans') else []) + ['barb|' + n, 'bar|most|%s|' % n, 'bar|total|%s|' % n] + ['bar|more|%s|%s>%s' % (n, a, b) for a in c for b in c]
    if k == 'chaosBars': return ['bar|most|%s|' % ','.join(map(str, s['counts']))]
    if k == 'rodMaker': return ['teen|read|%d' % s['n']] + ['teen|read|%d' % m for m in s.get('show', [])]
    if k in ('teenWrite', 'chaos31'): return ['teen|read|%d' % s['n']]
    if k == 'rodFactory': return ['teen|read|%d' % m for m in s['stops']]
    if k in ('countAllHook', 'chaosTakeMore'): return ['add|' + s2n([s['a'], s['b']])]
    if k == 'makeTenLab': return ['add|' + s2n([s['a'], s['b']]), 'sub|%d|%d' % (s['a'] + s['b'], s['b'])]
    if k == 'tenBus': return ['add|' + s2n([r['a'], r['b']]) for r in s['rounds']]
    if k == 'unitStrip': return ['meas|strip|%d' % s['n']]
    return []   # أصدقاء العشرة ولمحتها: ASSESS_ONLY
def before(L):   # ما قبل التمرين، ولعبةٌ بمشهدها الخاص (يعيشها الطفل في المسارين) — كما في d240
    out = set(); fl = L['flow']
    first = next((i for i, st in enumerate(fl) if st['s'] in ('practice', 'game') or (st.get('scene') == 'items' and st.get('mode') in ('practice', 'remedial'))), len(fl))
    def grab(v):
        if isinstance(v, list): [grab(x) for x in v]; return
        if not isinstance(v, dict): return
        if isinstance(v.get('t'), str) and fact(v): out.add(fact(v))
        if isinstance(v.get('scene'), str): out.update(f for f in scene_facts(v) if not ASSESS_ONLY.match(f))
        if isinstance(v.get('mat'), dict):   # ومسائل «معي» (مواصفات بنود {of: نوعه}) كما في d240
            for sp in v['mat'].get('facts') or []:
                f = fact({**sp, 't': sp['of']}) if isinstance(sp, dict) and 'of' in sp else None
                if f and not ASSESS_ONLY.match(f): out.add(f)
        for k, x in v.items():
            if k not in ('lines', 'labels', 'twin'): grab(x)
    for i, st in enumerate(fl):
        if i < first or (st['s'] == 'game' and st.get('scene') != 'items'): grab(st)
    return out
def _assess(L):   # بنود التقييم (الإتقان والبند المشتبك والمراجعة والاختبار): مسائلها لا تكون توائم في أي درس من الوحدة
    M = L.get('mastery', {})
    return [x for a in M.get('concepts', {}).values() for x in a] + ([M['mixed']['item']] if M.get('mixed') else []) + L.get('review', []) + [q['item'] for q in (L.get('test') or {}).get('items', [])]
LESSONS = [d1, d2, d3, d4, d5, d6, d7, d8]
ASSESS = {fact(x) for _L in LESSONS for x in _assess(_L) if isinstance(x, dict) and fact(x) and not ASSESS_ONLY.match(fact(x))}
def norm(it): return json.dumps({k: v for k, v in it.items() if k not in FMT}, ensure_ascii=False, sort_keys=True)
ASSESS_N = {norm(x) for _L in LESSONS for x in _assess(_L) if isinstance(x, dict) and isinstance(x.get('t'), str)}   # والبند نفسه ممنوع ولو كان عدّ فراغات (d240: items)
