# والتوأم بعد الكشف ليس جوابه في موضع جواب أصله ولونه، ولا يُرتَّب بتسلسل لمسه، ولا يُحلّ بالنهاية إن كان أصله لا يُحلّ بها (الفحص المستقل E1؛ وتفحصه 4ب11)
def _ans(v): L = v['lens']; return L.index((max if v.get('ask', 'long') == 'long' else min)(L))
def _shifted(v): return isinstance(v.get('shift'), list) and any(v['shift']) and not v.get('wavy')
def _byEnd(v):
    S = [(v.get('shift') or [0] * len(v['lens']))[i] or 0 for i in range(len(v['lens']))]; E = [S[i] + l for i, l in enumerate(v['lens'])]
    x = (max if v.get('ask', 'long') == 'long' else min)(E); return E[_ans(v)] == x   # والتساوي حلٌّ بالنهاية كما في lint (الفحص المستقل H1 (4))
def _seq(v): return sorted(range(len(v['vals'])), key=lambda i: -v['vals'][i] if v.get('dir', 'up') == 'down' else v['vals'][i])
def _endOrd(v):   # «رتّب» بالطول يُرتَّب بالنهايات: ترتيب النهايات هو ترتيب الأطوال (كما في 4ب8)
    S = v.get('shift') or [0] * len(v['vals']); I = range(len(v['vals']))
    return sorted(I, key=lambda i: v['vals'][i]) == sorted(I, key=lambda i: S[i] + v['vals'][i])
def twinOk(it, x, LN={}):
    if it.get('t') == 'lenPick' == x.get('t'):
        if _ans(x) == _ans(it): return False
        if _shifted(it) and not _byEnd(it) and _shifted(x) and _byEnd(x): return False
    if it.get('t') == 'orderBy' == x.get('t') and _seq(x) == _seq(it): return False
    if it.get('t') == 'orderBy' == x.get('t') and it.get('by', 'len') == 'len' and not _endOrd(it) and _endOrd(x): return False   # ولا يُرتَّب بالنهايات إن كان أصله لا يُرتَّب بها (J1 (1))
    if it.get('t') == 'transPick' == x.get('t'):   # توأم التعدّي يحفظ فخّ أصله (الفحص المستقل F1 (5)): فخّه من مهارته، ويسمّي سلّتيه إن سمّاهما أصله، وجوابه في الموضع الآخر
        named = lambda v: 'سَلَّةِ «' in str(LN.get(v['q'], ''))
        if named(x) != named(it) or _tpIdx(x) == _tpIdx(it): return False
    return True
def _tpIdx(v): return 0 if (v['la'] > v['lb']) == (v.get('ask', 'longer') == 'longer') else 1
def helpItems(L):
    for k in ('normal', 'challenge'): yield from L['practice'].get(k, [])
    for its in L.get('mastery', {}).get('remedial', {}).values(): yield from its
    for st in L['flow']:
        if st.get('scene') == 'items' and st.get('mode') in ('practice', 'remedial'): yield from st['items']
def twinPaths(L):   # ما يعيشه الطفل: التمرين العادي أو التحدّي (يختار أحدهما) ومعه ألعاب الدرس، ثم العلاج بعد الإتقان إن احتاجه
    fl = [x for st in L['flow'] if st.get('scene') == 'items' and st.get('mode') in ('practice', 'remedial') for x in st['items']]
    return {'A': L['practice'].get('normal', []) + fl, 'B': L['practice'].get('challenge', []) + fl,
            'C': [x for its in L.get('mastery', {}).get('remedial', {}).values() for x in its]}
def lineIds(v, out):
    if isinstance(v, str): out.add(v)
    elif isinstance(v, list): [lineIds(x, out) for x in v]
    elif isinstance(v, dict): [lineIds(x, out) for x in v.values()]
    return out
def attachTwins(L):
    """التوأم مسألة جديدة على الطفل في ما يعيشه (الدرس 132): لا يعيد ما قبل التمرين، ولا مسألة بندٍ في مساره ولا في العلاج بعده،
    ولا توأماً آخر في مساره؛ وتوأم العلاج لا يعيد شيئاً من المسارات. ومسائل التقييم في الوحدة كلها ممنوعة إلا ما يُحسب بين التقييمات وحدها
    (عدّ فراغات الإطار ولمحته، كما في d240). يُحلّ بالتراجع، ويحسمه build/d240.mjs."""
    T = TWINS[L['id']]; B0 = before(L); LN = {**L['lines'], **T['lines']}
    for k, xs in T['pool'].items():   # كل بند في المخزن بمهارة مفتاحه (الفحص المستقل F1 (5): كان tw.tr2 في مخزن غير مهارته)
        for x in xs: assert skill(x) == k, ('مخزن التوائم بغير مهارته', L['id'], k, x.get('q'), skill(x))
    P = twinPaths(L); items = []; seen = set()
    for k in ('A', 'B', 'C'):
        for it in P[k]:
            if id(it) not in seen: seen.add(id(it)); items.append(it)
    mem = {id(it): {k for k in P if any(x is it for x in P[k])} for it in items}
    F = {k: {tkey(x) for x in P[k]} for k in P}
    bad0 = B0 | ASSESS
    def forbid(it):
        m = mem[id(it)]; s = set(bad0) | {tkey(it)} | F['C']
        for k in ('A', 'B'):
            if k in m or 'C' in m: s |= F[k]
        return s
    def cands(it):
        c = [x for x in T['pool'].get(skill(it), [])] + [x for x in items if x is not it and skill(x) == skill(it)]
        out, fs = [], set()
        for x in c:
            f = tkey(x)
            if f in forbid(it) or f in fs or norm(x) in ASSESS_N or not twinOk(it, x, LN): continue
            fs.add(f); out.append(x)
        return out
    C = {id(it): cands(it) for it in items}
    for it in items: assert C[id(it)], ('لا توأم', L['id'], it.get('q'), skill(it), sorted(mem[id(it)]))
    def clash(a, fa, b, fb): return fa == fb and bool(mem[id(a)] & mem[id(b)])
    order = sorted(items, key=lambda it: len(C[id(it)])); pick = {}
    def solve(i):
        if i == len(order): return True
        it = order[i]
        # وتوأم العلاج يُختار أولاً مما لم يُختر توأماً في التمرين: طفلٌ في التمرين ثم في العلاج لا يرى التوأم نفسه مرتين
        cs = C[id(it)] if mem[id(it)] != {'C'} else sorted(C[id(it)], key=lambda x: sum(1 for o in order[:i] if tkey(pick[id(o)]) == tkey(x)))
        for x in cs:
            f = tkey(x)
            if any(clash(it, f, o, tkey(pick[id(o)])) for o in order[:i]): continue
            pick[id(it)] = x
            if solve(i + 1): return True
            del pick[id(it)]
        return False
    if not solve(0):
        for it in items: print('  ', it.get('q'), skill(it), sorted(mem[id(it)]), [tkey(x) for x in C[id(it)]])
        raise AssertionError(('لا توزيع للتوائم', L['id']))
    for it in items: it['twin'] = json.loads(json.dumps(pick[id(it)])); it['twin'].pop('twin', None)
    used = lineIds([it['twin'] for it in items], set())
    for k, v in T['lines'].items():
        if k in used: assert k not in L['lines'], (L['id'], k); L['lines'][k] = v
for _L in LESSONS: attachTwins(_L)
UNIT_U = {'clip': 28, 'cube': 42}
def _lens(v, where, out):
    if isinstance(v, list): [_lens(x, where, out) for x in v]; return
    if not isinstance(v, dict): return
    t = v.get('t')
    if t in ('unitCount', 'unitLay', 'unitCheck'): out.append((v['obj'], v['n'] * UNIT_U[v['unit']], where))
    if t == 'spanSort': out.append((v['obj'], v['len'], where))
    if t == 'transPick': out += [(v['a'], v['la'], where), (v['b'], v['lb'], where)]
    if t in ('orderBy', 'lenPick') and v.get('house'): out += [(o, (v.get('vals') or v.get('lens'))[i], where) for i, o in enumerate(v['house'])]
    if v.get('scene') == 'contractorBoard': out += [(o, L, where) for o, L in v['house']]
    for k, x in v.items():
        if k not in ('lines', 'labels'): _lens(x, where, out)
for _L in LESSONS:
    _o = []; _lens(_L, _L['id'], _o)
    for o, L, w in _o: assert LEN.get(o) == L, ('طول الشيء غير طوله في جدول الوحدة', w, o, L, LEN.get(o))

